import math

# Define the target number
target = 1560

# Function to find the prime factors of a number
def prime_factors(n):
    i = 2
    factors = {}
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            if i in factors:
                factors[i] += 1
            else:
                factors[i] = 1
    if n > 1:
        factors[n] = 1 if n not in factors else factors[n] + 1
    return factors

# Find the prime factors of the target number
